import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"FFI-Native Stdlib — Handl over Direct C/POSIX Bindings","description":"","frontmatter":{"title":"FFI-Native Stdlib — Handl over Direct C/POSIX Bindings","type":"adr","date":"2026-09-04T00:00:00.000Z","status":"accepted","status_note":"Accepted — native bodies are handl over direct C/POSIX FFI; Rust shrinks to the kernel.","refs":["ADR-0077","ADR-0069","ADR-0052","ADR-0081"]},"headers":[],"relativePath":"handl/project/adrs/0083-ffi-native-stdlib.md","filePath":"vendored/handl/project/adrs/0083-ffi-native-stdlib.md"}`),a={name:`handl/project/adrs/0083-ffi-native-stdlib.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0083-ffi-native-stdlib-—-handl-over-direct-c-posix-bindings" tabindex="-1">ADR-0083: FFI-Native Stdlib — Handl over Direct C/POSIX Bindings <a class="header-anchor" href="#adr-0083-ffi-native-stdlib-—-handl-over-direct-c-posix-bindings" aria-label="Permalink to “ADR-0083: FFI-Native Stdlib — Handl over Direct C/POSIX Bindings”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong><code>ffi_bind</code> is a host-exposed arrow op.</strong> A binding is data — library, symbol, signature, error clause — and is capability-gated like any host op.</li><li><strong>Marshalling is a closed ABI vocabulary</strong>: scalars, pointers, structs, <code>Bytes</code> for buffers, optional and variadic arguments, and an explicit handle lifecycle for opaque resources.</li><li><strong>Errors are declared per binding.</strong> An optional error clause maps <code>errno</code> (or a return code) to <code>Err</code>; no sentinel-value convention.</li><li><strong>A Rust FFI dispatcher does only the mechanics</strong>: load the library and symbol (cached), marshal, call, unmarshal, check the error clause.</li><li><strong>The abstraction layer is handl</strong>: POSIX wrappers, constants and the stdlib layout sit over <code>ffi_bind</code>; no per-library Rust remains.</li><li><strong>Platform variants are abstracted from day one</strong> (Linux first) and chosen by data, not <code>cfg</code>/<code>kind ==</code> branches.</li><li><strong>Rust keeps only the kernel</strong>: dispatcher, module loader, engines, host and the core value/runtime crates.</li><li><strong>What is eliminated</strong>: per-library Rust <code>Function</code> bodies and the <code>plugin-ffi-rust</code> closure layer (never built).</li><li><strong>The async runtime is handl-authored from day one</strong>: <code>epoll_wait</code> for readiness, handl task dispatch; non-blocking fds, <code>Suspend</code> on async ops, state machines rather than continuations.</li><li><strong>Kernel freedom</strong>: the kernel knows nothing of POSIX, libc or any library — every binding is data and every policy is handl.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>ADR-0077 moved the stdlib to handl but left native bodies as Rust <code>Function</code> impls, one per library, trusted to honor axioms nobody could check. Those bodies duplicated C signatures in Rust, blocked the self-hosting story, and put <code>cranelift</code>/<code>libloading</code> in every build. Direct FFI makes native access data and lets Rust shrink to the kernel.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep <code>plugin-ffi-rust</code> closure bindings</strong> — never built; the closure layer is the duplication this removes.</li><li><strong>One Rust wrapper per library</strong> — unverifiable, and it re-grows the crates ADR-0077 deleted.</li><li><strong>Put libc/POSIX knowledge in the kernel</strong> — it would make the kernel platform-bound and every target a kernel change.</li><li><strong>Write the async runtime in Rust</strong> — it would be the last per-platform library body; epoll + handl tasks is the same mechanism as data.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Native access is data; adding a library is a binding table, not a crate.</li><li><code>errno</code>/return-code clauses make failure explicit, but every binding author must state one — the compiler cannot infer it.</li><li>Opaque handles need an explicit lifecycle; leaks become the binding&#39;s documented responsibility.</li><li>The dispatcher is the only <code>unsafe</code> surface, and the kernel stays portable.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>crates/plugin-ffi/</code> — the dispatcher (load, marshal, call, unmarshal).</li><li><code>handl-packages/*/</code> — the <code>ffi_bind</code> tables and their error clauses.</li><li><code>kit-prelude-lang/</code> — the stdlib layout and POSIX constants.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The ABI vocabulary, dispatcher steps, async runtime, platform variants and the +tiered migration map: +<a href="./../design/0083-ffi-native-stdlib.html"><code>design/0083-ffi-native-stdlib.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};